import{_ as s,o as e,c as t,a2 as p}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"嘉景","description":"","frontmatter":{"title":"嘉景","date":"2026-11-20T00:00:00.000Z","seq":187,"categories":["美文","全宋词"],"collection":"《全宋词 · 柳永》","tags":["全宋词","宋"],"poem":true,"poem_quote":false,"author":"柳永","source_book":"全宋词","prev":{"text":"全吴嘉会古风流","link":"/blogs/全宋词·柳永/全吴嘉会古风流.html"},"next":{"text":"远岸收残雨","link":"/blogs/全宋词·柳永/远岸收残雨.html"}},"headers":[],"relativePath":"blogs/全宋词·柳永/嘉景.md","filePath":"blogs/全宋词·柳永/嘉景.md"}'),o={name:"blogs/全宋词·柳永/嘉景.md"};function l(n,a,c,m,r,_){return e(),t("div",null,[...a[0]||(a[0]=[p('<h1 id="嘉景" tabindex="-1">嘉景 <a class="header-anchor" href="#嘉景" aria-label="Permalink to &quot;嘉景&quot;">​</a></h1><p class="poem-meta">宋 · 柳永　·　洞仙歌</p><div class="poem"><p class="poem-stanza">嘉景，向少年彼此，争不雨沾云惹。</p><p class="poem-stanza">奈傅粉英俊，梦兰品雅。</p><p class="poem-stanza">金丝帐暖银屏亚。</p><p class="poem-stanza">并粲枕、轻偎轻倚，绿娇红姹。</p><p class="poem-stanza">算一笑，百琲明珠非价。</p><p class="poem-stanza">闲暇。</p><p class="poem-stanza">每祗向、洞房深处，痛怜极宠，似觉些子轻孤，早恁背人沾洒。</p><p class="poem-stanza">从来娇纵多猜讶。</p><p class="poem-stanza">更对翦香云，须要深心同写。</p><p class="poem-stanza">爱搵了双眉，索人重画。</p><p class="poem-stanza">忍孤艳冶。</p><p class="poem-stanza">断不等闲轻舍。</p><p class="poem-stanza">鸳衾下。</p><p class="poem-stanza">愿常恁、好天良夜。</p></div>',3)])])}const z=s(o,[["render",l]]);export{d as __pageData,z as default};
